UPDATE results SET statement_tex = 'Let $\psi$ be a primitive character, and let $\mathcal C_\psi$, $m_\chi$, $S_\rho$ and $Z$ be as in \hyperref[8JS4]{the definition}.
\begin{enumerate}
\item[(i)] For every primitive character $\chi$, $\overline{L(\bar s, \chi)} = L(s, \bar\chi)$ as meromorphic functions of $s \in \C$, and $m_{\bar\chi}(\bar\rho) = m_\chi(\rho)$ for every $\rho \in \C$.
\item[(ii)] $Z$ is locally finite and closed under complex conjugation.
\item[(iii)] $S_\rho > 0$ for every $\rho \in Z$.
\end{enumerate}', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:45:00', updated_by = 'claude' WHERE id = 118;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '118', 2, 'merge-8JS5-parts-2026-11-24', '{"tag":"8JS5","type":"lemma","title":"Conjugation and the zero set","statement_tex":"Let $\\psi$ be a primitive character, and let $\\mathcal C_\\psi$, $m_\\chi$, $S_\\rho$ and $Z$ be as in \\hyperref[8JS4]{the definition}.\n\\begin{enumerate}\n\\item[(i)] For every primitive character $\\chi$, $\\overline{L(\\bar s, \\chi)} = L(s, \\bar\\chi)$ as meromorphic functions of $s \\in \\C$, and $m_{\\bar\\chi}(\\bar\\rho) = m_\\chi(\\rho)$ for every $\\rho \\in \\C$.\n\\item[(ii)] $Z$ is locally finite and closed under complex conjugation.\n\\item[(iii)] $S_\\rho > 0$ for every $\\rho \\in Z$.\n\\end{enumerate}","section_id":104,"position":3,"listed":1,"aliases":["zero-set-properties"]}', 'claude');
UPDATE proofs SET body_tex = '\emph{(i)} For $\Re s > 1$ both sides equal $\sum_{n \ge 1} \bar\chi(n)\, n^{-s}$, so they agree on $\C$ by the identity theorem. Hence $L(s,\chi) = (s-\rho)^m g(s)$ with $g(\rho) \ne 0$ gives $L(s,\bar\chi) = (s-\bar\rho)^m\, \overline{g(\bar s)}$.

\emph{(ii)} $L(s,\chi)$ for $\chi \ne \mathbf 1$ and $(s-1)\zeta(s)$ are entire and not identically zero \cite{Davenport}, so their zeros are discrete; and $\mathcal C_\psi$ is finite. If $L(\rho,\chi) = 0$ with $\chi \in \mathcal C_\psi$, then $L(\bar\rho,\bar\chi) = 0$ by (i), and $\bar\chi \in \mathcal C_\psi$ by the \hyperref[8JG8]{definition} of the family.

\emph{(iii)} Some $m_\chi(\rho) \ge 1$, every term of $S_\rho$ is nonnegative, and $a_\chi > 0$.', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:45:00', updated_by = 'claude' WHERE id = 105;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '105', 3, 'merge-8JS5-parts-2026-11-24', '{"result_id":118,"body_tex":"\\emph{(i)} For $\\Re s > 1$ both sides equal $\\sum_{n \\ge 1} \\bar\\chi(n)\\, n^{-s}$, so they agree on $\\C$ by the identity theorem. Hence $L(s,\\chi) = (s-\\rho)^m g(s)$ with $g(\\rho) \\ne 0$ gives $L(s,\\bar\\chi) = (s-\\bar\\rho)^m\\, \\overline{g(\\bar s)}$.\n\n\\emph{(ii)} $L(s,\\chi)$ for $\\chi \\ne \\mathbf 1$ and $(s-1)\\zeta(s)$ are entire and not identically zero \\cite{Davenport}, so their zeros are discrete; and $\\mathcal C_\\psi$ is finite. If $L(\\rho,\\chi) = 0$ with $\\chi \\in \\mathcal C_\\psi$, then $L(\\bar\\rho,\\bar\\chi) = 0$ by (i), and $\\bar\\chi \\in \\mathcal C_\\psi$ by the \\hyperref[8JG8]{definition} of the family.\n\n\\emph{(iii)} Some $m_\\chi(\\rho) \\ge 1$, every term of $S_\\rho$ is nonnegative, and $a_\\chi > 0$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
UPDATE proofs SET body_tex = 'By \ref{8JS5}(i), $\overline{G_\chi} = G_{\bar\chi}$, so $\Re G_\chi = \frac12(G_\chi + G_{\bar\chi})$. As $\mathcal C_\psi$ is closed under $\chi \mapsto \bar\chi$,
\[ \Phi_\psi(s) = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi \bigl(H_\chi(s) + H_{\bar\chi}(s)\bigr) \qquad (\Re s > 1). \]
By \ref{8JS6}(ii) the right-hand side is meromorphic on $\Re s > 0$, its poles are simple and lie in $Z$, and at $\rho \in Z$
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi\, \frac{-m_\chi(\rho) - m_{\bar\chi}(\rho)}{\rho(\rho-1)} = -\frac{S_\rho}{\rho(\rho-1)}, \]
which is nonzero by \ref{8JS5}(iii).', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:45:00', updated_by = 'claude' WHERE id = 101;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '101', 4, 'merge-8JS5-parts-2026-11-24', '{"result_id":111,"body_tex":"By \\ref{8JS5}(i), $\\overline{G_\\chi} = G_{\\bar\\chi}$, so $\\Re G_\\chi = \\frac12(G_\\chi + G_{\\bar\\chi})$. As $\\mathcal C_\\psi$ is closed under $\\chi \\mapsto \\bar\\chi$,\n\\[ \\Phi_\\psi(s) = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(H_\\chi(s) + H_{\\bar\\chi}(s)\\bigr) \\qquad (\\Re s > 1). \\]\nBy \\ref{8JS6}(ii) the right-hand side is meromorphic on $\\Re s > 0$, its poles are simple and lie in $Z$, and at $\\rho \\in Z$\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi\\, \\frac{-m_\\chi(\\rho) - m_{\\bar\\chi}(\\rho)}{\\rho(\\rho-1)} = -\\frac{S_\\rho}{\\rho(\\rho-1)}, \\]\nwhich is nonzero by \\ref{8JS5}(iii).","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
UPDATE proofs SET body_tex = 'Since $L(s,\chi) \ne 0$ for $\Re s \ge 1$ \cite{Davenport}, a real $\rho \in Z$ lies in $(0,1)$. By \ref{8JN4} and \ref{8JS5}(iii),
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = \frac{S_\rho}{\rho(1-\rho)} > 0. \]', body_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 14:45:00', updated_by = 'claude' WHERE id = 107;
